function hashText(s) {
  let h = 2166136261;
  for (let i2 = 0; i2 < s.length; i2++) {
    h ^= s.charCodeAt(i2);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
var mcq = (level, stem, options, correct, solution, extra = {}) => {
  const from = "ABCD".indexOf(correct);
  const to = hashText(stem) % 4;
  const opts = [...options];
  [opts[from], opts[to]] = [opts[to], opts[from]];
  return {
    type: "mcq",
    level,
    stem,
    options: opts,
    correct: "ABCD"[to],
    solution,
    ...extra
  };
};
var tf = (level, stem, statements, solution) => ({
  type: "true_false",
  level,
  stem,
  statements,
  solution
});
var sa = (level, stem, accepted, solution, unit) => ({
  type: "short_answer",
  level,
  stem,
  accepted,
  solution,
  ...unit ? { unit } : {}
});
var es = (level, stem, solution, hint) => ({
  type: "essay",
  level,
  stem,
  solution,
  ...hint ? { hint } : {}
});
var ge = (level, stem, figure, solution, hint) => ({
  type: "geometry_essay",
  level,
  stem,
  figure,
  solution,
  ...hint ? { hint } : {}
});
var r3 = String.raw;

