// src/seed/toan8-lessons/index.ts
var TOAN8_LESSONS = [...CHUONG_12, ...CHUONG_22, ...CHUONG_32, ...CHUONG_42, ...CHUONG_52, ...CHUONG_62, ...CHUONG_72, ...CHUONG_82, ...CHUONG_92, ...CHUONG_102];

// src/seed/lesson-content.ts
async function applyLessonContent(db, log = console.log) {
  const book = await db.one(sql`select id from textbooks where slug = 'toan-8'`);
  if (!book) return 0;
  let applied = 0;
  const stats = { theory: 0, formulas: 0, examples: 0, kept: [] };
  for (const content of TOAN8_LESSONS) {
    const key = `toan8-v3:${content.slug}`;
    if (await db.one(sql`select 1 from seed_marks where key = ${key}`)) continue;
    await db.tx(async (t) => {
      const lesson = await t.one(sql`select id from lessons where textbook_id = ${book.id} and slug = ${content.slug}`);
      if (!lesson) throw new Error(`N\u1ED9i dung b\xE0i h\u1ECDc: kh\xF4ng t\xECm th\u1EA5y b\xE0i ${content.slug}`);
      await applyOne(t, lesson.id, content, stats);
      await t.exec(sql`insert into seed_marks (key, note) values (${key}, 'Nội dung bài học giai đoạn 3')`);
    });
    applied++;
  }
  if (applied) {
    log(`\u0110\xE3 n\u1EA1p n\u1ED9i dung ${applied} b\xE0i h\u1ECDc: ${stats.theory} m\u1EE5c ki\u1EBFn th\u1EE9c, ${stats.formulas} c\xF4ng th\u1EE9c, ${stats.examples} v\xED d\u1EE5 minh h\u1ECDa.`);
    if (stats.kept.length) log(`Gi\u1EEF nguy\xEAn l\xED thuy\u1EBFt gi\xE1o vi\xEAn \u0111\xE3 so\u1EA1n \u1EDF: ${stats.kept.join(", ")}.`);
  }
  return applied;
}
async function applyOne(t, lessonId, c, stats) {
  await t.exec(sql`update lessons set applications = coalesce(applications, ${c.applications}) where id = ${lessonId}`);
  const existing = await t.many(sql`
    select id, kind, title, body, solution from lesson_sections where lesson_id = ${lessonId} order by sort_order, id`);
  const original = TOAN8_CONTENT[c.slug]?.sections ?? [];
  const untouched = existing.length > 0 && existing.length === original.length && existing.every((s, i2) => s.kind === original[i2].kind && (s.title ?? null) === (original[i2].title ?? null) && s.body === original[i2].body && (s.solution ?? null) === (original[i2].solution ?? null));
  if (untouched) await t.exec(sql`delete from lesson_sections where lesson_id = ${lessonId}`);
  if (existing.length === 0 || untouched) {
    for (const [i2, it] of c.theory.entries()) {
      await t.exec(sql`
        insert into lesson_sections (lesson_id, kind, title, body, formula, example, sort_order)
        values (${lessonId}, ${it.kind}, ${it.title}, ${it.body}, ${it.formula ?? null}, ${it.example ?? null}, ${i2 + 1})`);
      stats.theory++;
    }
  } else stats.kept.push(c.slug);
  if (!await t.one(sql`select 1 from formulas where lesson_id = ${lessonId}`)) {
    let n2 = 0;
    for (const g of c.formulas) {
      for (const f of g.items) {
        await t.exec(sql`
          insert into formulas (lesson_id, group_title, name, tex, symbols, condition, example, sort_order)
          values (${lessonId}, ${g.group}, ${f.name}, ${f.tex}, ${f.symbols}, ${f.condition ?? null}, ${f.example}, ${++n2})`);
        stats.formulas++;
      }
    }
  }
  for (const [slug, examples] of Object.entries(c.examples)) {
    const topic = await t.one(sql`select id from topics where lesson_id = ${lessonId} and slug = ${slug}`);
    if (!topic) throw new Error(`N\u1ED9i dung b\xE0i h\u1ECDc ${c.slug}: kh\xF4ng t\xECm th\u1EA5y d\u1EA1ng to\xE1n ${slug}`);
    if (await t.one(sql`select 1 from worked_examples where topic_id = ${topic.id}`)) continue;
    for (const [i2, e] of examples.entries()) {
      await t.exec(sql`
        insert into worked_examples (topic_id, level, problem, analysis, knowledge, given, to_prove, figure, steps, answer, tip, sort_order)
        values (${topic.id}, ${e.level}, ${e.problem}, ${e.analysis}, ${e.knowledge}, ${e.given ?? null}, ${e.toProve ?? null}, ${e.figure ?? null},
          ${JSON.stringify(e.steps)}::jsonb, ${e.answer}, ${e.tip ?? null}, ${i2 + 1})`);
      stats.examples++;
    }
  }
  for (const [slug, note] of Object.entries(c.notes ?? {})) {
    await t.exec(sql`update topics set notes = coalesce(notes, ${note}) where lesson_id = ${lessonId} and slug = ${slug}`);
  }
}

// src/seed/run.ts
var LABELS_MCQ = ["A", "B", "C", "D"];
var LABELS_TF = ["a", "b", "c", "d"];
async function seedBase(db) {
  await db.exec(sql`insert into subjects (code, name) values ('toan', 'Toán') on conflict (code) do nothing`);
  for (const level of [6, 7, 8, 9]) {
    await db.exec(sql`
      insert into grades (level, name, status, sort_order)
      values (${level}, ${"L\u1EDBp " + level}, ${level === 8 ? "active" : "coming_soon"}, ${level})
      on conflict (level) do nothing`);
  }
  for (const [i2, a] of ACHIEVEMENTS.entries()) {
    await db.exec(sql`
      insert into achievements (code, name, description, icon, tier, xp_reward, sort_order)
      values (${a.code}, ${a.name}, ${a.description}, ${a.icon}, ${a.tier}, ${a.xp}, ${i2 + 1})
      on conflict (code) do update set name = excluded.name, description = excluded.description,
        icon = excluded.icon, tier = excluded.tier, xp_reward = excluded.xp_reward, sort_order = excluded.sort_order`);
  }
}
async function seedToan8(db, log = console.log) {
  const exists = await db.one(sql`select id from textbooks where slug = 'toan-8'`);
  if (exists) return false;
  await db.tx(async (t) => {
    const subject = await t.one(sql`select id from subjects where code = 'toan'`);
    const grade = await t.one(sql`select id from grades where level = 8`);
    const book = await t.one(sql`
      insert into textbooks (subject_id, grade_id, slug, title, series, series_code, program, description, status, is_default)
      values (${subject.id}, ${grade.id}, 'toan-8', 'Toán 8', 'Kết nối tri thức với cuộc sống', 'kntt', 'GDPT 2018',
        'Toán 8 theo bộ sách Kết nối tri thức với cuộc sống, Chương trình giáo dục phổ thông 2018.', 'published', true)
      returning id`);
    const textbookId = book.id;
    const semesterIds = {};
    for (const n2 of [1, 2]) {
      const s = await t.one(sql`
        insert into semesters (textbook_id, number, name) values (${textbookId}, ${n2}, ${n2 === 1 ? "H\u1ECDc k\xEC I" : "H\u1ECDc k\xEC II"}) returning id`);
      semesterIds[n2] = s.id;
    }
    const lessonIds = /* @__PURE__ */ new Map();
    const topicIds = /* @__PURE__ */ new Map();
    for (const [ci, ch2] of TOAN8_CHAPTERS.entries()) {
      const chapter = await t.one(sql`
        insert into chapters (textbook_id, semester_id, code, title, description, kind, sort_order)
        values (${textbookId}, ${semesterIds[ch2.semester]}, ${ch2.code}, ${ch2.title}, ${ch2.description ?? null}, ${ch2.kind}, ${ci + 1})
        returning id`);
      for (const [li, l] of ch2.lessons.entries()) {
        const content = TOAN8_CONTENT[l.slug];
        const lesson = await t.one(sql`
          insert into lessons (textbook_id, chapter_id, number, slug, title, kind, summary, periods, estimated_minutes, status, sort_order)
          values (${textbookId}, ${chapter.id}, ${l.number ?? null}, ${l.slug}, ${l.title}, ${l.kind}, ${content?.summary ?? null},
            ${l.periods}, ${content?.minutes ?? l.periods * 45}, 'published', ${li + 1})
          returning id`);
        lessonIds.set(l.slug, lesson.id);
        if (content) {
          for (const [si, s] of content.sections.entries()) {
            await t.exec(sql`
              insert into lesson_sections (lesson_id, kind, title, body, solution, sort_order)
              values (${lesson.id}, ${s.kind}, ${s.title ?? null}, ${s.body}, ${s.solution ?? null}, ${si + 1})`);
          }
        }
        const ids = [];
        for (const [ti, title] of (l.topics ?? []).entries()) {
          const topic = await t.one(sql`
            insert into topics (lesson_id, title, method, sort_order)
            values (${lesson.id}, ${title}, ${content?.methods?.[ti] ?? null}, ${ti + 1}) returning id`);
          ids.push(topic.id);
        }
        topicIds.set(l.slug, ids);
      }
    }
    const plan = await t.one(sql`
      insert into teaching_plans (textbook_id, school_year, title)
      values (${textbookId}, '2026-2027', 'Phân phối chương trình Toán 8 – năm học 2026-2027') returning id`);
    for (const [i2, item] of TOAN8_PPCT_2026.entries()) {
      await t.exec(sql`
        insert into teaching_plan_items (plan_id, position, title, lesson_id, periods, period_from, period_to, weeks, equipment, note)
        values (${plan.id}, ${i2 + 1}, ${item.title}, ${item.lesson ? lessonIds.get(item.lesson) ?? null : null}, ${item.periods},
          ${item.from}, ${item.to}, ${item.weeks}, ${item.equipment ?? null}, ${item.note ?? null})`);
    }
    for (const q of TOAN8_QUESTIONS) {
      const lessonId = lessonIds.get(q.lesson);
      if (!lessonId) throw new Error("C\xE2u h\u1ECFi m\u1EABu tham chi\u1EBFu b\xE0i kh\xF4ng t\u1ED3n t\u1EA1i: " + q.lesson);
      const topicId = q.topic !== void 0 ? topicIds.get(q.lesson)?.[q.topic] ?? null : null;
      await insertSeedQuestion(t, textbookId, lessonId, topicId, q, "C\xE2u h\u1ECFi m\u1EABu \u2013 T\u1EA1 H\u1EEFu Th\u1EAFng");
    }
  });
  log(`\u0110\xE3 t\u1EA1o ch\u01B0\u01A1ng tr\xECnh To\xE1n 8 KNTT: ${TOAN8_CHAPTERS.length} ch\u01B0\u01A1ng, ${TOAN8_PPCT_2026.length} m\u1EE5c PPCT, ${TOAN8_QUESTIONS.length} c\xE2u h\u1ECFi m\u1EABu.`);
  return true;
}
async function insertSeedQuestion(t, textbookId, lessonId, topicId, q, source) {
  const settings = q.type === "short_answer" ? { tolerance: 0, ...q.unit ? { unit: q.unit } : {} } : {};
  const row = await t.one(sql`
    insert into questions (exercise_type_id, textbook_id, lesson_id, topic_id, level, stem, settings, points, status, source)
    values ((select id from exercise_types where code = ${q.type}), ${textbookId}, ${lessonId}, ${topicId}, ${q.level}, ${q.stem},
      ${settings}, 1, 'published', ${source})
    returning id`);
  const qid = row.id;
  if (q.type === "mcq") {
    for (const [i2, opt] of q.options.entries()) {
      await t.exec(sql`insert into answers (question_id, label, content, is_correct, sort_order)
        values (${qid}, ${LABELS_MCQ[i2]}, ${opt}, ${LABELS_MCQ[i2] === q.correct}, ${i2 + 1})`);
    }
  } else if (q.type === "true_false") {
    for (const [i2, [text3, ok]] of q.statements.entries()) {
      await t.exec(sql`insert into answers (question_id, label, content, is_correct, sort_order)
        values (${qid}, ${LABELS_TF[i2]}, ${text3}, ${ok}, ${i2 + 1})`);
    }
  } else if (q.type === "short_answer") {
    for (const [i2, a] of q.accepted.entries()) {
      await t.exec(sql`insert into answers (question_id, label, content, is_correct, sort_order)
        values (${qid}, ${String(i2 + 1)}, ${a}, true, ${i2 + 1})`);
    }
  }
  await t.exec(sql`insert into solutions (question_id, kind, content) values (${qid}, 'full', ${q.solution})`);
  if (q.hint) await t.exec(sql`insert into solutions (question_id, kind, content, sort_order) values (${qid}, 'hint', ${q.hint}, 1)`);
  if (q.figure) {
    const img = await t.one(sql`
      insert into images (kind, figure_source, alt) values ('figure', ${q.figure}, 'Hình vẽ minh họa đề bài') returning id`);
    await t.exec(sql`insert into question_images (question_id, image_id, sort_order) values (${qid}, ${img.id}, 0)`);
  }
  return qid;
}
async function seedAll(db, log = console.log) {
  await seedBase(db);
  await seedToan8(db, log);
  await applyKnowledgeMap(db, log);
  await applyLessonContent(db, log);
}

