function emptyQuestionInput(type) {
  return {
    type,
    lessonId: null,
    topicId: null,
    level: 1,
    points: 1,
    status: "published",
    stem: "",
    options: ["", "", "", ""],
    correct: "",
    statements: ["a", "b", "c", "d"].map(() => ({ text: "", value: null })),
    accepted: [],
    tolerance: 0,
    unit: "",
    solution: "",
    hint: "",
    figure: ""
  };
}
function questionToInput(qf) {
  const input = emptyQuestionInput(qf.type);
  input.lessonId = qf.lessonId;
  input.topicId = qf.topicId;
  input.level = qf.level;
  input.points = qf.points;
  input.status = qf.status === "archived" ? "draft" : qf.status;
  input.stem = qf.stem;
  if (qf.type === "mcq") {
    input.options = ["A", "B", "C", "D"].map((l) => qf.answers.find((a) => a.label === l)?.content ?? "");
    input.correct = qf.answers.find((a) => a.isCorrect)?.label ?? "";
  }
  if (qf.type === "true_false") {
    input.statements = ["a", "b", "c", "d"].map((l) => {
      const a = qf.answers.find((x) => x.label === l);
      return { text: a?.content ?? "", value: a ? a.isCorrect : null };
    });
  }
  if (qf.type === "short_answer") {
    input.accepted = qf.answers.map((a) => a.content);
    input.tolerance = qf.settings.tolerance ?? 0;
    input.unit = qf.settings.unit ?? "";
  }
  input.solution = qf.solution ?? "";
  input.hint = qf.hint ?? "";
  input.figure = qf.images.find((i2) => i2.kind === "figure")?.figureSource ?? "";
  return input;
}
function parseQuestionForm(form) {
  const errors = [];
  const type = form.str("type");
  if (!QUESTION_TYPES.includes(type)) return { input: emptyQuestionInput("mcq"), errors: ["Lo\u1EA1i c\xE2u h\u1ECFi kh\xF4ng h\u1EE3p l\u1EC7."] };
  const input = emptyQuestionInput(type);
  input.lessonId = form.int("lesson_id");
  input.topicId = form.int("topic_id");
  input.level = Math.min(4, Math.max(1, form.int("level") ?? 1));
  input.points = form.num("points") ?? 1;
  input.status = form.str("status") === "draft" ? "draft" : "published";
  input.stem = form.text("stem", 8e3).trim();
  input.solution = form.text("solution", 8e3).trim();
  input.hint = form.text("hint", 2e3).trim();
  input.figure = form.text("figure", 4e3).trim();
  if (!input.stem) errors.push("Ch\u01B0a nh\u1EADp n\u1ED9i dung c\xE2u h\u1ECFi.");
  if (!(input.points > 0 && input.points <= 100)) errors.push("\u0110i\u1EC3m c\u1EE7a c\xE2u h\u1ECFi ph\u1EA3i l\u1EDBn h\u01A1n 0 v\xE0 kh\xF4ng qu\xE1 100.");
  if (!input.lessonId) errors.push("Ch\u1ECDn b\xE0i h\u1ECDc cho c\xE2u h\u1ECFi.");
  const texts = [["\u0110\u1EC1 b\xE0i", input.stem], ["L\u1EDDi gi\u1EA3i", input.solution], ["G\u1EE3i \xFD", input.hint]];
  if (type === "mcq") {
    input.options = ["A", "B", "C", "D"].map((l) => form.text(`option_${l}`, 2e3).trim());
    input.correct = form.str("correct");
    input.options.forEach((o, i2) => {
      if (!o) errors.push(`Ph\u01B0\u01A1ng \xE1n ${"ABCD"[i2]} \u0111ang \u0111\u1EC3 tr\u1ED1ng.`);
      texts.push([`Ph\u01B0\u01A1ng \xE1n ${"ABCD"[i2]}`, o]);
    });
    if (!/^[A-D]$/.test(input.correct)) errors.push("Ch\u1ECDn ph\u01B0\u01A1ng \xE1n \u0111\xFAng.");
    const nonEmpty = input.options.filter(Boolean);
    if (new Set(nonEmpty.map((o) => o.replace(/\s+/g, ""))).size < nonEmpty.length) errors.push("C\xF3 hai ph\u01B0\u01A1ng \xE1n tr\xF9ng nhau.");
  }
  if (type === "true_false") {
    input.statements = ["a", "b", "c", "d"].map((l) => {
      const v = form.str(`tf_${l}`);
      return { text: form.text(`stmt_${l}`, 2e3).trim(), value: v === "true" ? true : v === "false" ? false : null };
    });
    input.statements.forEach((s, i2) => {
      const l = "abcd"[i2];
      if (!s.text) errors.push(`\xDD ${l}) \u0111ang \u0111\u1EC3 tr\u1ED1ng.`);
      if (s.value === null) errors.push(`Ch\u1ECDn \u0110\xFAng ho\u1EB7c Sai cho \xFD ${l}).`);
      texts.push([`\xDD ${l})`, s.text]);
    });
  }
  if (type === "short_answer") {
    input.accepted = form.text("accepted", 1e3).split("\n").map((s) => s.trim()).filter(Boolean).slice(0, 10);
    input.tolerance = Math.abs(form.num("tolerance") ?? 0);
    input.unit = form.str("unit", 20);
    if (!input.accepted.length) errors.push("Nh\u1EADp \xEDt nh\u1EA5t m\u1ED9t \u0111\xE1p \xE1n \u0111\u01B0\u1EE3c ch\u1EA5p nh\u1EADn (m\u1ED7i d\xF2ng m\u1ED9t \u0111\xE1p \xE1n).");
  }
  if (type === "geometry_essay" && !input.figure) errors.push('C\xE2u t\u1EF1 lu\u1EADn h\xECnh h\u1ECDc c\u1EA7n h\xECnh v\u1EBD (m\xF4 t\u1EA3 b\u1EB1ng v\u0103n b\u1EA3n \u1EDF \xF4 "H\xECnh v\u1EBD").');
  if (input.figure) {
    const { errors: figErrors } = figureToSvg(input.figure);
    figErrors.forEach((e) => errors.push("H\xECnh v\u1EBD \u2013 " + e));
  }
  for (const [name, text3] of texts) {
    if (text3) findMathErrors(text3).forEach((e) => errors.push(`${name}: ${e}`));
  }
  return { input, errors };
}
async function resolveLessonTopic(q, textbookId, input) {
  if (input.topicId) {
    const t = await q.one(sql`
      select t.lesson_id, l.textbook_id from topics t join lessons l on l.id = t.lesson_id where t.id = ${input.topicId}`);
    if (!t || t.textbookId !== textbookId) return "D\u1EA1ng to\xE1n kh\xF4ng h\u1EE3p l\u1EC7.";
    if (input.lessonId && input.lessonId !== t.lessonId) return "D\u1EA1ng to\xE1n \u0111\xE3 ch\u1ECDn kh\xF4ng thu\u1ED9c b\xE0i h\u1ECDc \u0111\xE3 ch\u1ECDn.";
    input.lessonId = t.lessonId;
  }
  if (input.lessonId) {
    const l = await q.one(sql`select 1 from lessons where id = ${input.lessonId} and textbook_id = ${textbookId}`);
    if (!l) return "B\xE0i h\u1ECDc kh\xF4ng h\u1EE3p l\u1EC7.";
  }
  return null;
}
async function saveQuestion(db, id, textbookId, input, userId) {
  return db.tx(async (t) => {
    const problem = await resolveLessonTopic(t, textbookId, input);
    if (problem) return { error: problem };
    const settings = input.type === "short_answer" ? { tolerance: input.tolerance, ...input.unit ? { unit: input.unit } : {} } : {};
    let qid = id;
    if (qid) {
      await t.exec(sql`
        update questions set exercise_type_id = (select id from exercise_types where code = ${input.type}), lesson_id = ${input.lessonId},
          topic_id = ${input.topicId}, level = ${input.level}, stem = ${input.stem}, settings = ${settings}, points = ${input.points},
          status = ${input.status}, updated_at = now()
        where id = ${qid}`);
      await t.exec(sql`delete from answers where question_id = ${qid}`);
      await t.exec(sql`delete from solutions where question_id = ${qid}`);
    } else {
      const row = await t.one(sql`
        insert into questions (exercise_type_id, textbook_id, lesson_id, topic_id, level, stem, settings, points, status, created_by)
        values ((select id from exercise_types where code = ${input.type}), ${textbookId}, ${input.lessonId}, ${input.topicId}, ${input.level},
          ${input.stem}, ${settings}, ${input.points}, ${input.status}, ${userId})
        returning id`);
      qid = row.id;
    }
    if (input.type === "mcq") {
      for (const [i2, text3] of input.options.entries()) {
        const label = "ABCD"[i2];
        await t.exec(sql`insert into answers (question_id, label, content, is_correct, sort_order) values (${qid}, ${label}, ${text3}, ${label === input.correct}, ${i2 + 1})`);
      }
    } else if (input.type === "true_false") {
      for (const [i2, s] of input.statements.entries()) {
        await t.exec(sql`insert into answers (question_id, label, content, is_correct, sort_order) values (${qid}, ${"abcd"[i2]}, ${s.text}, ${!!s.value}, ${i2 + 1})`);
      }
    } else if (input.type === "short_answer") {
      for (const [i2, a] of input.accepted.entries()) {
        await t.exec(sql`insert into answers (question_id, label, content, is_correct, sort_order) values (${qid}, ${String(i2 + 1)}, ${a}, true, ${i2 + 1})`);
      }
    }
    if (input.solution) await t.exec(sql`insert into solutions (question_id, kind, content) values (${qid}, 'full', ${input.solution})`);
    if (input.hint) await t.exec(sql`insert into solutions (question_id, kind, content, sort_order) values (${qid}, 'hint', ${input.hint}, 1)`);
    await t.exec(sql`
      delete from images where id in (
        select i.id from question_images qi join images i on i.id = qi.image_id where qi.question_id = ${qid} and i.kind = 'figure')`);
    if (input.figure) {
      const img = await t.one(sql`
        insert into images (kind, figure_source, alt, created_by) values ('figure', ${input.figure}, 'Hình vẽ minh họa đề bài', ${userId}) returning id`);
      await t.exec(sql`insert into question_images (question_id, image_id, sort_order) values (${qid}, ${img.id}, 0)`);
    }
    return { id: qid };
  });
}
async function deleteQuestion(db, id) {
  return db.tx(async (t) => {
    const used = await t.one(sql`select count(*)::int as n from test_questions where question_id = ${id}`);
    const answered = await t.one(sql`select count(*)::int as n from question_responses where question_id = ${id}`);
    if ((used?.n ?? 0) > 0 || (answered?.n ?? 0) > 0) {
      await t.exec(sql`update questions set status = 'archived', updated_at = now() where id = ${id}`);
      return "archived";
    }
    await t.exec(sql`delete from images where id in (select image_id from question_images where question_id = ${id}) and kind = 'figure'`);
    await t.exec(sql`delete from questions where id = ${id}`);
    return "deleted";
  });
}
async function duplicateQuestion(db, id, userId) {
  const qf = await getQuestion(db, id);
  if (!qf) return null;
  const input = questionToInput(qf);
  input.status = "draft";
  const res = await saveQuestion(db, null, qf.textbookId, input, userId);
  return res.id ?? null;
}
function canEditQuestion(q, user) {
  return user.role === "admin" || q.createdBy === null || q.createdBy === user.id;
}

