    if (test.attempts >= test.maxAttempts) throw new UserInputError("B\u1EA1n \u0111\xE3 d\xF9ng h\u1EBFt s\u1ED1 l\u1EA7n l\xE0m b\xE0i.");
    await t.one(sql`select id from tests where id = ${testId} for update`);
