    input.status = status2;
    if (!type) errors.push(`H\xECnh th\u1EE9c "${get("hinh_thuc")}" kh\xF4ng h\u1EE3p l\u1EC7 (d\xF9ng TN, DS, TLN, TL ho\u1EB7c HH).`);
