async function testAction(ctx) {
  const user = requireTeacher(ctx);
  const { test } = await loadTest(ctx);
  const base = `/giao-vien/de-kiem-tra/${test.id}`;
  const form = await ctx.form();
  const action = ctx.params.action ?? "info";
  try {
    switch (action) {
      case "info": {
        const input = readTestForm(form);
        const errors = validateTestInput(input);
        if (errors.length) return testDetailPage(ctx, errors);
        await updateTest(ctx.db, test.id, input);
        return redirect(base, { type: "success", message: "\u0110\xE3 l\u01B0u th\xF4ng tin \u0111\u1EC1." }, ctx);
      }
      case "cau-hoi": {
        const ids = form.all("question_id").map(Number).filter((n2) => Number.isInteger(n2) && n2 > 0).slice(0, 100);
        if (!ids.length) return redirect(base, { type: "error", message: "Ch\u01B0a ch\u1ECDn c\xE2u h\u1ECFi n\xE0o." }, ctx);
        await addQuestionsToTest(ctx.db, test.id, ids);
        return redirect(base, { type: "success", message: `\u0110\xE3 th\xEAm ${ids.length} c\xE2u v\xE0o \u0111\u1EC1.` }, ctx);
      }
      case "lop": {
        const ids = form.all("class_id").map(Number).filter((n2) => Number.isInteger(n2) && n2 > 0);
        await setAssignments(ctx.db, test.id, user, ids);
        return redirect(base, { type: "success", message: "\u0110\xE3 l\u01B0u danh s\xE1ch l\u1EDBp \u0111\u01B0\u1EE3c giao." }, ctx);
      }
      case "trang-thai": {
        const status2 = form.str("status");
        if (!["draft", "published", "closed"].includes(status2)) throw new HttpError(400);
        if (status2 === "draft" && await hasSubmissions(ctx.db, test.id)) throw new UserInputError("\u0110\u1EC1 \u0111\xE3 c\xF3 b\xE0i l\xE0m, kh\xF4ng th\u1EC3 chuy\u1EC3n v\u1EC1 nh\xE1p.");
        await setTestStatus(ctx.db, test, status2);
        return redirect(base, { type: "success", message: status2 === "published" ? "\u0110\xE3 ph\xE1t \u0111\u1EC1 cho c\xE1c l\u1EDBp \u0111\u01B0\u1EE3c giao." : status2 === "closed" ? "\u0110\xE3 \u0111\xF3ng \u0111\u1EC1." : "\u0110\xE3 chuy\u1EC3n \u0111\u1EC1 v\u1EC1 b\u1EA3n nh\xE1p." }, ctx);
      }
      case "xoa":
        await deleteTest(ctx.db, test.id);
        return redirect("/giao-vien/de-kiem-tra", { type: "success", message: "\u0110\xE3 x\xF3a \u0111\u1EC1." }, ctx);
      default:
        throw new HttpError(404);
    }
  } catch (err) {
    if (err instanceof UserInputError) return redirect(base, { type: "error", message: err.message }, ctx);
    throw err;
  }
}
async function testQuestionAction(ctx) {
  const { test } = await loadTest(ctx);
  const qid = intParam(ctx, "qid");
  const base = `/giao-vien/de-kiem-tra/${test.id}`;
  const form = await ctx.form();
  try {
    switch (form.str("_action")) {
      case "remove":
        await removeQuestionFromTest(ctx.db, test.id, qid);
        break;
      case "up":
        await moveQuestionInTest(ctx.db, test.id, qid, -1);
        break;
      case "down":
        await moveQuestionInTest(ctx.db, test.id, qid, 1);
        break;
      case "points":
        await setQuestionPoints(ctx.db, test.id, qid, form.num("points") ?? 0);
        break;
      default:
        throw new HttpError(400);
    }
  } catch (err) {
    if (err instanceof UserInputError) return redirect(base, { type: "error", message: err.message }, ctx);
    throw err;
  }
  return redirect(base);
}
