async function gradingAction(ctx) {
  const { user, attempt } = await loadAttemptForGrading(ctx);
  const form = await ctx.form();
  const responseId = form.int("response_id");
  const points = form.num("points");
  const questions = await resultDetails(ctx.db, attempt, false);
  const q = questions.find((x) => x.responseId === responseId);
  if (!q || q.autoGraded) throw new HttpError(400, "C\xE2u kh\xF4ng c\u1EA7n ch\u1EA5m tay.");
  if (points === null) return gradingPage(ctx, ["Nh\u1EADp \u0111i\u1EC3m cho c\xE2u."]);
  try {
    await gradeManual(ctx.db, attempt, responseId, points, q.testPoints, form.str("feedback", 1e3), user.id);
  } catch (err) {
    if (err instanceof UserInputError) return gradingPage(ctx, [err.message]);
    throw err;
  }
  return redirect(`/giao-vien/cham-bai/${attempt.id}`, { type: "success", message: "\u0110\xE3 l\u01B0u \u0111i\u1EC3m." }, ctx);
}

