  server.headersTimeout = 3e4;
  server.requestTimeout = 6e4;
  server.listen(cfg.port, cfg.host, () => {
    console.log(`${BRAND} \u0111ang ch\u1EA1y t\u1EA1i http://${cfg.host === "0.0.0.0" ? "localhost" : cfg.host}:${cfg.port}`);
  });
