      console.log(applied.length ? `\u0110\xE3 \xE1p d\u1EE5ng: ${applied.join(", ")}` : "C\u01A1 s\u1EDF d\u1EEF li\u1EC7u \u0111\xE3 \u1EDF phi\xEAn b\u1EA3n m\u1EDBi nh\u1EA5t.");
